from itertools import combinations as C
R=set('ABCDEF'); S=[('F','C'),('AC','D'),('AD','BEF')]
def cl(X,F):
    X=set(X)
    while any(set(l)<=X and not set(r)<=X for l,r in F):
        for l,r in F:
            if set(l)<=X: X|=set(r)
    return X
def keys(F):
    K=[]
    for n in range(1,7):
        for c in C('ABCDEF',n):
            if not any(k<=set(c) for k in K) and cl(c,F)>=R: K.append(set(c))
    return K
def nf(F):
    K=keys(F); P=set().union(*K); bc=n3=n2=False
    for n in range(1,6):
        for c in C('ABCDEF',n):
            X=set(c)
            for a in cl(X,F)-X:
                if not cl(X,F)>=R:
                    bc=True
                    if a not in P:
                        n3=True
                        if any(X<k for k in K): n2=True
    return '1NF' if n2 else '2NF' if n3 else '3NF' if bc else 'BCNF'
def dp(D,F):
    G=[(set(c),cl(c,F)&set(Ri)-set(c)) for Ri in D for n in range(1,len(Ri)) for c in C(Ri,n)]
    return all(set(r)<=cl(l,G) for l,r in F)
def lj(D,F):
    A='ABCDEF'; T=[['a'+c if c in Ri else 'b%d'%i+c for c in A] for i,Ri in enumerate(D)]; ch=True
    while ch:
        ch=False
        for l,r in F:
            for i in range(len(D)):
