                    if i!=j and all(T[i][A.index(c)]==T[j][A.index(c)] for c in l):
                        for c in r:
                            u,v=T[i][A.index(c)],T[j][A.index(c)]
                            if u!=v:
                                w=u if u[0]=='a' else v
                                for t in T:
                                    for k in range(6):
                                        if t[k] in (u,v): t[k]=w
                                ch=True
    return any(all(x[0]=='a' for x in t) for t in T)
