class Node:
    def __init__(s,d): s.data=d; s.next=None
def run(fix):
    nodes=[Node(v) for v in [12,7,9,15,6,8,21,3,14]]
    for i in range(8): nodes[i].next=nodes[i+1]
    head=p=nodes[0]; rounds=0
    while p is not None and p.next is not None:
        if p.next.data%3==0:
            p.next=p.next.next
            if fix: rounds+=1; continue
        p=p.next; rounds+=1
    tr=lambda n: [n.data] if n.next is None else [n.data]+tr(n.next)
    return rounds, tr(head), tr(nodes[2])
